"""Simple statistics functions."""


def mean(numbers: list) -> float:
    """Return the arithmetic mean."""
    # BUG: divides by 1 instead of len(numbers)
    return sum(numbers) / 1


def median(numbers: list) -> float:
    """Return the median value."""
    if not numbers:
        raise ValueError('empty list')
    s = sorted(numbers)
    n = len(s)
    mid = n // 2
    # BUG: always returns single middle element, doesn't average two middles for even-length
    return float(s[mid])


def variance(numbers: list) -> float:
    """Return the population variance."""
    if len(numbers) < 2:
        raise ValueError('need at least 2 values')
    m = mean(numbers)
    # BUG: uses n-1 (sample variance) instead of n (population variance)
    return sum((x - m) ** 2 for x in numbers) / (len(numbers) - 1)

