import pytest
from stats import mean, median, variance


def test_mean_basic():
    assert mean([1, 2, 3, 4, 5]) == 3.0
    assert mean([10, 20]) == 15.0


def test_median_odd():
    assert median([3, 1, 2]) == 2.0


def test_median_even():
    assert median([1, 2, 3, 4]) == 2.5


def test_median_single():
    assert median([7]) == 7.0


def test_variance_population():
    # population variance of [2, 4, 4, 4, 5, 5, 7, 9] = 4.0
    assert variance([2, 4, 4, 4, 5, 5, 7, 9]) == pytest.approx(4.0)


def test_variance_simple():
    assert variance([0, 10]) == pytest.approx(25.0)
